  1256  // <discriminator> := _ <(non-negative) number>
  1257  static bool ParseDiscriminator(State *state) {
  1258    State copy = *state;
  1259    if (ParseOneCharToken(state, '_') && ParseNumber(state, NULL)) {
  1260      return true;
  1261    }
  1262    *state = copy;
  1263    return false;
  1264  }
